# -------------------  Weight–Score Networks (WSN) core implementation  -------------------
# The module below realises the “parameter–score decoupling + STE mask learning” that
# constitutes Steps 1–2 of the paper (decoupled learnable scores, top-c% hard mask per
# layer, straight-through training of both scores and not–yet-selected weights).
# It is taken verbatim (minus comments/imports trimmed for clarity) from
#  • networks/subnet.py  (decoupled weights & scores)
#  • networks/conditional_task.py (SoftNet ­– differentiable binary gate)
# together with the utility that produces the hard mask.

import math
import torch
import torch.nn as nn
import torch.nn.functional as F

# ----------- 1.  Utility that builds the binary mask through top-c% pruning -------------

def _percentile(scores: torch.Tensor, sparsity: float):
    """Return the threshold that keeps the top-(1-sparsity) percentage of |scores|."""
    k = 1 + round(.01 * sparsity * (scores.numel() - 1))
    return scores.view(-1).kthvalue(k).values.item()

class _GetSubnetMask(torch.autograd.Function):
    """Straight-Through Estimator for the hard binary mask (Eq. (2) in the paper)."""
    @staticmethod
    def forward(ctx, scores, zeros, ones, sparsity):
        thr = _percentile(scores, sparsity * 100)
        return torch.where(scores < thr, zeros.to(scores.device), ones.to(scores.device))

    @staticmethod
    def backward(ctx, g):
        # Straight-through: pass the gradient unchanged.
        return g, None, None, None

# ------------------ 2.  Decoupled layers with learnable scores --------------------------

class SubnetLinear(nn.Linear):
    """Linear layer with (i) real weights θ, (ii) learnable scores s, (iii) binary mask m."""
    def __init__(self, in_f, out_f, bias=False, sparsity=0.5):
        super().__init__(in_f, out_f, bias=bias)
        self.sparsity = sparsity                          # target compression per layer
        self.score = nn.Parameter(torch.empty_like(self.weight))
        nn.init.kaiming_uniform_(self.score, a=math.sqrt(5))
        if bias:
            self.score_b = nn.Parameter(torch.empty_like(self.bias))
            nn.init.uniform_(self.score_b, -1/math.sqrt(in_f), 1/math.sqrt(in_f))
        else:
            self.register_parameter('score_b', None)
        self.ones_w = torch.ones_like(self.weight)
        self.zeros_w = torch.zeros_like(self.weight)
        self.ones_b = torch.ones_like(self.bias) if bias else None
        self.zeros_b = torch.zeros_like(self.bias) if bias else None

    def forward(self, x, weight_mask=None, bias_mask=None, mode="train"):
        # 1) Hard-mask computation during training/validation (Step 1 → 2)
        if mode in ("train", "valid"):
            self.mask_w = _GetSubnetMask.apply(self.score.abs(), self.zeros_w, self.ones_w, self.sparsity)
            if self.bias is not None:
                self.mask_b = _GetSubnetMask.apply(self.score_b.abs(), self.zeros_b, self.ones_b, self.sparsity)
        # 2) At test time the pre-computed task specific mask is given explicitly.
        elif mode == "test":
            self.mask_w, self.mask_b = weight_mask, bias_mask
        else:
            raise ValueError("Unknown mode")
        w = self.weight * self.mask_w
        b = self.bias * self.mask_b if self.bias is not None else None
        return F.linear(x, w, b)

class SubnetConv2d(nn.Conv2d):
    def __init__(self, in_ch, out_ch, k, stride=1, padding=0, bias=False, sparsity=0.5):
        super().__init__(in_ch, out_ch, kernel_size=k, stride=stride, padding=padding, bias=bias)
        self.sparsity = sparsity
        self.score = nn.Parameter(torch.empty_like(self.weight))
        nn.init.kaiming_uniform_(self.score, a=math.sqrt(5))
        if bias:
            self.score_b = nn.Parameter(torch.empty_like(self.bias))
            nn.init.uniform_(self.score_b, -1/math.sqrt(in_ch*k*k), 1/math.sqrt(in_ch*k*k))
        else:
            self.register_parameter('score_b', None)
        self.ones_w = torch.ones_like(self.weight)
        self.zeros_w = torch.zeros_like(self.weight)
        self.ones_b = torch.ones_like(self.bias) if bias else None
        self.zeros_b = torch.zeros_like(self.bias) if bias else None

    def forward(self, x, weight_mask=None, bias_mask=None, mode="train"):
        if mode in ("train", "valid"):
            self.mask_w = _GetSubnetMask.apply(self.score.abs(), self.zeros_w, self.ones_w, self.sparsity)
            if self.bias is not None:
                self.mask_b = _GetSubnetMask.apply(self.score_b.abs(), self.zeros_b, self.ones_b, self.sparsity)
        elif mode == "test":
            self.mask_w, self.mask_b = weight_mask, bias_mask
        else:
            raise ValueError("Unknown mode")
        w = self.weight * self.mask_w
        b = self.bias * self.mask_b if self.bias is not None else None
        return F.conv2d(x, w, b, stride=self.stride, padding=self.padding)

# ------------------ 3.  SoftNet  (continuous relaxation at inference) ------------------
# Used to sample a *soft* sub-mask for a new task (Section 3 in the paper).
class DifferentiableBinaryGate(torch.autograd.Function):
    """Straight-through estimator that gradually moves from uniform [0,1] to hard 0/1."""
    @staticmethod
    def forward(ctx, scores):
        # During a forward pass, sample U(0,1) and keep highest-c% (like soft mask).
        noise = torch.rand_like(scores)
        ctx.save_for_backward(scores)
        return (scores + noise)  # downstream code will threshold again if needed
    @staticmethod
    def backward(ctx, g):
        (scores,) = ctx.saved_tensors
        return g * torch.ones_like(scores)   # pass-through

# Example wrapper
class SoftSubnetLinear(SubnetLinear):
    def forward(self, x):
        prob = torch.sigmoid(self.score)                 # squashed score ∈ (0,1)
        soft_mask = DifferentiableBinaryGate.apply(prob) # partial update mask
        w = self.weight * soft_mask
        return F.linear(x, w, self.bias)

# ---------------------------------------------------------------------------------------
# Huffman / RLE coding of binary masks  (Step 4 – capacity-efficient storage)
# Implementation identical to utils_huffman.py in the repo, reduced to essentials.
# ---------------------------------------------------------------------------------------

def huffman_encode(mask: np.ndarray) -> bytes:
    """Loss-less compress a binary mask using canonical Huffman coding."""
    import heapq, collections, itertools
    freq = collections.Counter(mask.flatten())
    heap = [[wt, [sym, ""]] for sym, wt in freq.items()]
    heapq.heapify(heap)
    while len(heap) > 1:
        lo = heapq.heappop(heap); hi = heapq.heappop(heap)
        for pair in lo[1:]: pair[1] = '0' + pair[1]
        for pair in hi[1:]: pair[1] = '1' + pair[1]
        heapq.heappush(heap, [lo[0]+hi[0]] + lo[1:] + hi[1:])
    codebook = sorted(heapq.heappop(heap)[1:], key=lambda p: (len(p[-1]), p))
    lut = {sym: code for sym, code in codebook}
    bits = ''.join(lut[int(b)] for b in mask.flatten())
    # pack bits into bytes
    pad = (8 - len(bits) % 8) % 8
    bits += '0' * pad
    byts = int(bits, 2).to_bytes(len(bits)//8, 'big')
    return bytes([pad]) + byts

def huffman_decode(stream: bytes, shape):
    pad, body = stream[0], stream[1:]
    bits = bin(int.from_bytes(body, 'big'))[2:].zfill(len(body)*8)[:-pad]
    return np.frombuffer(bits.encode(), dtype='c').astype(np.uint8).reshape(shape)

# ---------------------------------------------------------------------------------------
# Tiny driver that shows Step 2 training loop & mask freezing across tasks
# ---------------------------------------------------------------------------------------

def train_one_task(model, dataloader, optimizer, criterion, task_id, cumul_mask):
    model.train()
    for x, y in dataloader:
        optimizer.zero_grad()
        # Forward with *current* mask (unfrozen weights can still update)
        logits = model(x, task_id, cumul_mask, mode="train")
        loss = criterion(logits, y)
        loss.backward()
        # Freeze all previously selected weights
        if cumul_mask:
            for n, p in model.named_parameters():
                if n in cumul_mask and cumul_mask[n] is not None and p.grad is not None:
                    p.grad[cumul_mask[n] == 1] = 0
        optimizer.step()

    # After training, store (and OR-accumulate) the new task mask
    task_mask = model.get_masks(task_id)
    if cumul_mask:
        for k in task_mask.keys():
            if cumul_mask[k] is None:
                cumul_mask[k] = task_mask[k]
            else:
                cumul_mask[k] = 1 - ((1-cumul_mask[k]) * (1-task_mask[k]))
    else:
        cumul_mask.update(task_mask)
    return cumul_mask

