# src/strategies/lpr_plugin.py  (Layer-wise Proximal Re-parameterisation – "Method")
# ---------------------------------------------
from avalanche.training.plugins.strategy_plugin import SupervisedPlugin
from dataclasses import dataclass
import torch
import torch.nn as nn
from typing import Any, Dict, Tuple
import wandb


@dataclass
class PreconditionerInv:
    matrix: torch.Tensor
    has_bias: bool
    parallel: bool = False


class LPRPlugin(SupervisedPlugin):
    """
    Layer-wise pre-conditioning of the SGD step, as described in the paper:
        Θ^{ℓ}_{j+1} = Θ^{ℓ}_{j} – η P_ℓ^{-1} ∇L(Θ^{ℓ}_{j})
    where  P_ℓ = I + ω_ℓ Z_ℓ^T Z_ℓ  (Z_ℓ are hidden activations of replay samples).

    • preconditioner_config holds ω₀ and β hyper-parameters (optionally layer-type specific).
    • update_config controls when/how the statistics (Z_ℓ) are recomputed.
    • At training-time (after backward) the plugin left-multiplies each layer’s
      gradient by the stored inverse preconditioner.
    """

    def __init__(self, lpr_kwargs, storage_policy):
        # config sections come directly from the Hydra YAML files
        self.preconditioner_config = lpr_kwargs['preconditioner']  # ω0, β …
        self.update_config         = lpr_kwargs['update']          # T, n_data …
        self.log_config            = lpr_kwargs['log']             # logging cadence
        self.storage_policy        = storage_policy

        self._preconditioner_invs: Dict[str, PreconditionerInv] = dict()

    # ------------------------------------------------------------
    # HOOKS
    # ------------------------------------------------------------
    @torch.no_grad()
    def before_backward(self, strategy, **kwargs):
        # If necessary recompute P_ℓ^{-1}
        if self._should_update_preconditioners(strategy):
            self._set_preconditioner_invs(strategy)

    @torch.no_grad()
    def after_backward(self, strategy, **kwargs):
        # Apply P_ℓ^{-1} to every layer gradient
        if len(self.storage_policy.buffer) == 0:
            return

        log_grad_norms = (
            self.log_config.grad_norms
            and strategy.clock.train_exp_counter % self.log_config.grad_norms == 0
            and strategy.clock.train_exp_iterations in [0, strategy.train_epochs - 1]
        )

        result_dict, grad_norm_dict = precondition_gradient(
            model=strategy.model,
            preconditioner_invs=self._preconditioner_invs,
            calculate_norm=log_grad_norms,
        )
        if log_grad_norms:
            log_grad_norms_to_wandb(result_dict, grad_norm_dict)

    # ------------------------------------------------------------
    # INTERNALS
    # ------------------------------------------------------------
    def _should_update_preconditioners(self, strategy) -> bool:
        return (
            len(self.storage_policy.buffer) > 0
            and strategy.clock.train_iterations % self.update_config.every_iter == 0
        )

    def _set_preconditioner_invs(self, strategy):
        layer_stats = self._compute_layer_statistics(strategy)
        self._preconditioner_invs = self._compute_preconditioner_invs(layer_stats)

    @torch.no_grad()
    def _compute_layer_statistics(self, strategy):
        """Compute ω_ℓ Z_ℓ^T Z_ℓ   on replay buffer."""
        result = None
        model, device = strategy.model, strategy.device

        def retain(layer_dict, name):
            def _hook(m, inp, out):
                layer_dict[name] = dict(module=m, acts=inp[0].detach())
            return _hook

        n_seen, n_data = 0, self.update_config.n_data or len(self.storage_policy.buffer)
        loader = torch.utils.data.DataLoader(
            self.storage_policy.buffer,
            shuffle=True,
            batch_size=min(self.update_config.batch_size, n_data),
        )

        for batch in loader:
            if n_seen >= n_data:
                break
            X = batch[0].to(device)
            n_seen += len(X)

            layers_info, hooks = dict(), []
            for name, module in model.named_modules():
                if isinstance(module, (nn.Linear, nn.Conv2d, nn.BatchNorm2d)):
                    hooks.append(module.register_forward_hook(retain(layers_info, name)))

            was_training = strategy.is_training
            model.eval(); strategy.is_training = False
            model(X)
            if was_training:
                model.train(); strategy.is_training = True
            for h in hooks:
                h.remove()

            if result is None:
                result = {k: dict(ucov=0., n_samples=0, has_bias=False) for k in layers_info}

            for lname, info in layers_info.items():
                module, acts = info['module'], info['acts']
                if isinstance(module, nn.Conv2d):
                    ucov, n_acts_pd, has_bias = compute_conv_ucov(acts, module)
                elif isinstance(module, nn.Linear):
                    ucov, n_acts_pd, has_bias = compute_linear_ucov(acts, module)
                else:  # BatchNorm2d
                    ucovs, n_acts_pd, has_bias = compute_bn_ucov(acts, module)
                omega_0 = get_omega_0(self.preconditioner_config, module)
                c_layer = get_c_layer(self.preconditioner_config, module, n_acts_pd)
                omega0_layer = omega_0 / c_layer
                if isinstance(module, (nn.Conv2d, nn.Linear)):
                    result[lname]['ucov'] += omega0_layer * ucov.to(device)
                else:  # BN: list per channel
                    if isinstance(result[lname]['ucov'], float):
                        result[lname]['ucov'] = [0.] * len(ucovs)
                    for c, P in enumerate(ucovs):
                        result[lname]['ucov'][c] += omega0_layer * P.to(device)
                result[lname]['n_samples'] += len(X)
                result[lname]['has_bias'] = has_bias

        # normalise by #samples
        for stats in result.values():
            if isinstance(stats['ucov'], list):
                stats['ucov'] = [P / stats['n_samples'] for P in stats['ucov']]
            else:
                stats['ucov'] = stats['ucov'] / stats['n_samples']
        return result

    @torch.no_grad()
    def _compute_preconditioner_invs(self, layer_stats):
        def inv(ucov):
            I = torch.eye(ucov.size(0), device=ucov.device)
            return (ucov + I).inverse()

        precon_invs = {}
        for lname, stats in layer_stats.items():
            ucov, bias = stats['ucov'], stats['has_bias']
            if isinstance(ucov, list):
                mats = torch.stack([inv(u) for u in ucov], 0)
                precon_invs[lname] = PreconditionerInv(mats, bias, parallel=True)
            else:
                precon_invs[lname] = PreconditionerInv(inv(ucov), bias)
        return precon_invs


# ------------------------------------------------------------
# Helper functions – covariance, projection, logging
# ------------------------------------------------------------

def compute_conv_ucov(acts, module):
    k, s, p, d = module.kernel_size, module.stride, module.padding, module.dilation
    has_bias = module.bias is not None
    unfolded = nn.Unfold(k, d, p, s)(acts).transpose(-1, -2).reshape(-1, acts.size(1) * k[0] * k[1])
    if has_bias:
        unfolded = torch.cat((unfolded, torch.ones(unfolded.size(0), 1, device=acts.device)), 1)
    ucov = unfolded.T @ unfolded
    n_per_data = unfolded.size(0) // acts.size(0)
    return ucov, n_per_data, has_bias


def compute_linear_ucov(acts, module):
    has_bias = module.bias is not None
    if has_bias:
        acts = torch.cat((acts, torch.ones(acts.size(0), 1, device=acts.device)), 1)
    ucov = acts.T @ acts
    return ucov, 1, has_bias


def compute_bn_ucov(acts, module):
    has_bias = module.bias is not None
    acts_flat = acts.transpose(0, 1).flatten(1)
    mean = module.running_mean if module.track_running_stats else acts_flat.mean(1)
    var = module.running_var if module.track_running_stats else acts_flat.var(1, unbiased=False)
    acts_flat = (acts_flat - mean.view(-1, 1)) / (var.view(-1, 1) + module.eps)
    ucovs = []
    for c in range(acts_flat.size(0)):
        a = acts_flat[c]
        if has_bias:
            a = torch.stack((a, torch.ones_like(a)), 0)
        ucovs.append(a @ a.T)
    n_per_data = acts.size(-2) * acts.size(-1)
    return ucovs, n_per_data, has_bias


def precondition_gradient(model, preconditioner_invs, calculate_norm=False):
    res, layer_norms = {}, {}
    total_g, total_gn = 0., 0.
    for name, mod in model.named_modules():
        if name not in preconditioner_invs:
            continue
        inv = preconditioner_invs[name]
        g_w = mod.weight.grad.view(mod.weight.size(0), -1)
        if inv.has_bias:
            g_b = mod.bias.grad.view(mod.bias.size(0), -1)
            g = torch.cat((g_w, g_b), 1)
        else:
            g = g_w
        expr = 'CD,CDE->CE' if inv.parallel else 'CD,DE->CE'
        g_new = torch.einsum(expr, g, inv.matrix)
        if inv.has_bias:
            g_w_new, g_b_new = g_new[..., :-1], g_new[..., -1:]
            mod.weight.grad.copy_(g_w_new.view_as(mod.weight))
            mod.bias.grad.copy_(g_b_new.view_as(mod.bias))
        else:
            mod.weight.grad.copy_(g_new.view_as(mod.weight))
        if calculate_norm:
            g_norm, gn_norm = g.norm(), g_new.norm()
            layer_norms[name] = dict(g=g_norm.item(), g_new=gn_norm.item(), g_norm_ratio=gn_norm/g_norm)
            total_g += g_norm**2; total_gn += gn_norm**2
    if calculate_norm and total_g > 0:
        res = {
            'Grad Norm': total_g**0.5,
            'Projected Grad Norm': total_gn**0.5,
            'Grad Norm Projection Ratio': (total_gn/total_g)**0.5,
        }
    return res, layer_norms


def get_omega_0(cfg, module):
    if isinstance(module, nn.Linear) and cfg.linear_omega_0 is not None:
        return cfg.linear_omega_0
    if isinstance(module, nn.Conv2d)  and cfg.conv_omega_0  is not None:
        return cfg.conv_omega_0
    if isinstance(module, nn.BatchNorm2d) and cfg.bn_omega_0 is not None:
        return cfg.bn_omega_0
    return cfg.omega_0


def get_c_layer(cfg, module, n_acts):
    beta = cfg.beta
    if isinstance(module, nn.Conv2d)  and cfg.conv_beta is not None:
        beta = cfg.conv_beta
    if isinstance(module, nn.BatchNorm2d) and cfg.bn_beta  is not None:
        beta = cfg.bn_beta
    return n_acts ** beta


def log_grad_norms_to_wandb(result_dict, norm_dict):
    wd = {f"LPR/{k}": v for k, v in result_dict.items()}
    for lname, d in norm_dict.items():
        wd.update({f"LPR/{lname}/{k}": v for k, v in d.items()})
    wandb.log(wd, commit=False)

